ALTER TABLE "paustik_marketplace"."delivery_agent_profiles" ADD COLUMN "service_city" TEXT, ADD COLUMN "service_latitude" DECIMAL(10,7), ADD COLUMN "service_longitude" DECIMAL(10,7), ADD COLUMN "service_radius_meters" INTEGER NOT NULL DEFAULT 8000, ADD COLUMN "is_available" BOOLEAN NOT NULL DEFAULT false;
ALTER TABLE "paustik_marketplace"."deliveries" ADD COLUMN "estimated_payout" DECIMAL(12,2), ADD COLUMN "estimated_distance_km" DECIMAL(10,3), ADD COLUMN "estimation_rule" JSONB;
CREATE TABLE "paustik_marketplace"."earnings_estimate_policies" ("id" UUID NOT NULL PRIMARY KEY, "mother_basis_points" INTEGER NOT NULL, "courier_base" DECIMAL(10,2) NOT NULL, "included_km" DECIMAL(6,2) NOT NULL, "per_km" DECIMAL(10,2) NOT NULL, "courier_cap" DECIMAL(10,2) NOT NULL, "is_active" BOOLEAN NOT NULL DEFAULT true, "created_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP);
ALTER TABLE "paustik_marketplace"."earnings_estimate_policies" ADD CONSTRAINT "valid_estimate_policy" CHECK (mother_basis_points BETWEEN 0 AND 10000 AND courier_base >= 9 AND courier_cap >= courier_base AND per_km >= 0 AND included_km >= 0);
CREATE UNIQUE INDEX "one_active_earnings_estimate_policy" ON "paustik_marketplace"."earnings_estimate_policies" ("is_active") WHERE "is_active" = true;
